def timed(fn):
    """记录耗时的装饰器。"""

    def wrapper(*args, **kwargs):
        t0 = time.time()
        try:
            return fn(*args, **kwargs)
        finally:
            elapsed = time.time() - t0
            wrapper.last_elapsed = elapsed
    return wrapper
